import { createHmac, createHash } from "node:crypto";
import type { SourceReplyDeliveryMode } from "../auto-reply/get-reply-options.types.js";
import type { ReasoningLevel, ThinkLevel } from "../auto-reply/thinking.js";
import { SILENT_REPLY_TOKEN } from "../auto-reply/tokens.js";
import {
  hasNativeApprovalPromptRuntimeCapability,
  isKnownNativeApprovalPromptChannel,
} from "../channels/plugins/native-approval-prompt.js";
import type { MemoryCitationsMode } from "../config/types.memory.js";
import { buildMemoryPromptSection } from "../plugins/memory-state.js";
import {
  normalizeLowercaseStringOrEmpty,
  normalizeOptionalLowercaseString,
} from "../shared/string-coerce.js";
import { listDeliverableMessageChannels } from "../utils/message-channel.js";
import type { BootstrapMode } from "./bootstrap-mode.js";
import {
  buildFullBootstrapPromptLines,
  buildLimitedBootstrapPromptLines,
} from "./bootstrap-prompt.js";
import type { ResolvedTimeFormat } from "./date-time.js";
import type { EmbeddedContextFile } from "./pi-embedded-helpers.js";
import type {
  EmbeddedFullAccessBlockedReason,
  EmbeddedSandboxInfo,
} from "./pi-embedded-runner/types.js";
import {
  normalizePromptCapabilityIds,
  normalizeStructuredPromptSection,
} from "./prompt-cache-stability.js";
import { sanitizeForPromptLiteral } from "./sanitize-for-prompt.js";
import { SYSTEM_PROMPT_CACHE_BOUNDARY } from "./system-prompt-cache-boundary.js";
import type {
  ProviderSystemPromptContribution,
  ProviderSystemPromptSectionId,
} from "./system-prompt-contribution.js";
import type { PromptMode, SilentReplyPromptMode } from "./system-prompt.types.js";

/**
 * Controls which hardcoded sections are included in the system prompt.
 * - "full": All sections (default, for main agent)
 * - "minimal": Reduced sections (Tooling, Workspace, Runtime) - used for subagents
 * - "none": Just basic identity line, no sections
 */
type OwnerIdDisplay = "raw" | "hash";

const CONTEXT_FILE_ORDER = new Map<string, number>([
  ["agents.md", 10],
  ["soul.md", 20],
  ["identity.md", 30],
  ["user.md", 40],
  ["tools.md", 50],
  ["bootstrap.md", 60],
  ["memory.md", 70],
]);

const DYNAMIC_CONTEXT_FILE_BASENAMES = new Set(["heartbeat.md"]);
const DEFAULT_HEARTBEAT_PROMPT_CONTEXT_BLOCK =
  "Default heartbeat prompt:\n`Read HEARTBEAT.md if it exists (workspace context). Follow it strictly. Do not infer or repeat old tasks from prior chats. If nothing needs attention, reply HEARTBEAT_OK.`";
const SYSTEM_PROMPT_STABLE_PREFIX_CACHE_LIMIT = 64;

type StablePromptPrefixCacheEntry = {
  value: string;
};

const stablePromptPrefixCache = new Map<string, StablePromptPrefixCacheEntry>();

function cacheStablePromptPrefix(key: string, build: () => string): string {
  const cached = stablePromptPrefixCache.get(key);
  if (cached) {
    stablePromptPrefixCache.delete(key);
    stablePromptPrefixCache.set(key, cached);
    return cached.value;
  }

  const value = build();
  stablePromptPrefixCache.set(key, { value });
  while (stablePromptPrefixCache.size > SYSTEM_PROMPT_STABLE_PREFIX_CACHE_LIMIT) {
    const oldestKey = stablePromptPrefixCache.keys().next().value;
    if (oldestKey === undefined) {
      break;
    }
    stablePromptPrefixCache.delete(oldestKey);
  }
  return value;
}

function hashStablePromptInput(value: unknown): string {
  const hash = createHash("sha256");
  hash.update(JSON.stringify(value));
  return hash.digest("hex");
}

function normalizeContextFilePath(pathValue: string): string {
  return pathValue.trim().replace(/\\/g, "/");
}

function getContextFileBasename(pathValue: string): string {
  const normalizedPath = normalizeContextFilePath(pathValue);
  return normalizeLowercaseStringOrEmpty(normalizedPath.split("/").pop() ?? normalizedPath);
}

function isDynamicContextFile(pathValue: string): boolean {
  return DYNAMIC_CONTEXT_FILE_BASENAMES.has(getContextFileBasename(pathValue));
}

function isBootstrapContextFile(pathValue: string): boolean {
  return /(^|[\\/])BOOTSTRAP\.md$/iu.test(pathValue.trim());
}

function sanitizeContextFileContentForPrompt(content: string): string {
  // Claude Code subscription mode rejects this exact prompt-policy quote when it
  // appears in system context. The live heartbeat user turn still carries the
  // actual instruction, and the generated heartbeat section below covers behavior.
  return content.replaceAll(DEFAULT_HEARTBEAT_PROMPT_CONTEXT_BLOCK, "").replace(/\n{3,}/g, "\n\n");
}

function sortContextFilesForPrompt(contextFiles: EmbeddedContextFile[]): EmbeddedContextFile[] {
  return contextFiles.toSorted((a, b) => {
    const aPath = normalizeContextFilePath(a.path);
    const bPath = normalizeContextFilePath(b.path);
    const aBase = getContextFileBasename(a.path);
    const bBase = getContextFileBasename(b.path);
    const aOrder = CONTEXT_FILE_ORDER.get(aBase) ?? Number.MAX_SAFE_INTEGER;
    const bOrder = CONTEXT_FILE_ORDER.get(bBase) ?? Number.MAX_SAFE_INTEGER;
    if (aOrder !== bOrder) {
      return aOrder - bOrder;
    }
    if (aBase !== bBase) {
      return aBase.localeCompare(bBase);
    }
    return aPath.localeCompare(bPath);
  });
}

function buildProjectContextSection(params: {
  files: EmbeddedContextFile[];
  heading: string;
  dynamic: boolean;
}) {
  if (params.files.length === 0) {
    return [];
  }
  const lines = [params.heading, ""];
  if (params.dynamic) {
    lines.push(
      "The following frequently-changing project context files are kept below the cache boundary when possible:",
      "",
    );
  } else {
    const hasSoulFile = params.files.some(
      (file) => getContextFileBasename(file.path) === "soul.md",
    );
    lines.push("The following project context files have been loaded:");
    if (hasSoulFile) {
      lines.push(
        "If SOUL.md is present, embody its persona and tone. Avoid stiff, generic replies; follow its guidance unless higher-priority instructions override it.",
      );
    }
    lines.push("");
  }
  for (const file of params.files) {
    lines.push(`## ${file.path}`, "", sanitizeContextFileContentForPrompt(file.content), "");
  }
  return lines;
}

function buildHeartbeatSection(params: { isMinimal: boolean; heartbeatPrompt?: string }) {
  if (params.isMinimal || !params.heartbeatPrompt) {
    return [];
  }
  return [
    "## Heartbeats",
    "If the current user message is a heartbeat poll and nothing needs attention, reply exactly:",
    "HEARTBEAT_OK",
    'If something needs attention, do NOT include "HEARTBEAT_OK"; reply with the alert text instead.',
    "",
  ];
}

function buildExecApprovalPromptGuidance(params: {
  runtimeChannel?: string;
  inlineButtonsEnabled?: boolean;
  runtimeCapabilities?: readonly string[];
}) {
  const runtimeChannel = normalizeOptionalLowercaseString(params.runtimeChannel);
  const usesNativeApprovalUi =
    params.inlineButtonsEnabled ||
    hasNativeApprovalPromptRuntimeCapability(params.runtimeCapabilities) ||
    isKnownNativeApprovalPromptChannel(runtimeChannel);
  if (usesNativeApprovalUi) {
    return 'When exec returns approval-pending on this channel, rely on native approval card/buttons when they appear and do not also send plain chat /approve instructions. Only include the concrete /approve command if the tool result says chat approvals are unavailable or only manual approval is possible; when needed, copy the exact /approve command from the tool output\'s "Reply with:" line.';
  }
  return 'When exec returns approval-pending, include the concrete /approve command from the tool output\'s "Reply with:" line as plain chat text for the user, and do not ask for a different or rotated code.';
}

function buildSkillsSection(params: { skillsPrompt?: string; readToolName: string }) {
  const trimmed = params.skillsPrompt?.trim();
  if (!trimmed) {
    return [];
  }
  return [
    "## Skills (mandatory)",
    "Before replying: scan <available_skills> <description> entries.",
    `- If exactly one skill clearly applies: read its SKILL.md at <location> with \`${params.readToolName}\`, then follow it.`,
    "- If multiple could apply: choose the most specific one, then read/follow it.",
    "- If none clearly apply: do not read any SKILL.md.",
    "Constraints: never read more than one skill up front; only read after selecting.",
    "- When a skill drives external API writes, assume rate limits: prefer fewer larger writes, avoid tight one-item loops, serialize bursts when possible, and respect 429/Retry-After.",
    trimmed,
    "",
  ];
}

function buildMemorySection(params: {
  isMinimal: boolean;
  includeMemorySection?: boolean;
  availableTools: Set<string>;
  citationsMode?: MemoryCitationsMode;
}) {
  if (params.isMinimal || params.includeMemorySection === false) {
    return [];
  }
  return buildMemoryPromptSection({
    availableTools: params.availableTools,
    citationsMode: params.citationsMode,
  });
}

export function buildAgentBootstrapSystemContext(params: {
  bootstrapMode?: BootstrapMode;
  hasBootstrapFileInProjectContext?: boolean;
}): string[] {
  if (!params.bootstrapMode || params.bootstrapMode === "none") {
    return [];
  }
  if (params.bootstrapMode === "limited") {
    return [
      "## Bootstrap Pending",
      ...buildLimitedBootstrapPromptLines({
        introLine:
          "Bootstrap is still pending for this workspace, but this run cannot safely complete the full BOOTSTRAP.md workflow here.",
        nextStepLine:
          "Typical next steps include switching to a primary interactive run with normal workspace access or having the user complete the canonical BOOTSTRAP.md deletion afterward.",
      }),
      "",
    ];
  }
  return [
    "## Bootstrap Pending",
    ...buildFullBootstrapPromptLines({
      readLine: params.hasBootstrapFileInProjectContext
        ? "BOOTSTRAP.md is included below in Project Context; follow it before replying normally."
        : "Please read BOOTSTRAP.md from the workspace and follow it before replying normally.",
      firstReplyLine:
        "Your first user-visible reply for a bootstrap-pending workspace must follow BOOTSTRAP.md, not a generic greeting.",
    }),
    "",
  ];
}

export function buildAgentBootstrapSystemPromptSupplement(params: {
  bootstrapMode?: BootstrapMode;
  bootstrapTruncationNotice?: string;
  contextFiles?: EmbeddedContextFile[];
}): string | undefined {
  const supplement = buildAgentBootstrapSystemPromptSections({
    ...params,
    includeProjectContext: true,
  })
    .join("\n")
    .trim();
  return supplement.length > 0 ? supplement : undefined;
}

export function buildAgentBootstrapSystemPromptSections(params: {
  bootstrapMode?: BootstrapMode;
  bootstrapTruncationNotice?: string;
  contextFiles?: EmbeddedContextFile[];
  includeProjectContext?: boolean;
}): string[] {
  const bootstrapFiles =
    params.bootstrapMode === "full"
      ? sortContextFilesForPrompt(params.contextFiles ?? []).filter((file) =>
          isBootstrapContextFile(file.path),
        )
      : [];
  const lines = [
    ...buildAgentBootstrapSystemContext({
      bootstrapMode: params.bootstrapMode,
      hasBootstrapFileInProjectContext: bootstrapFiles.length > 0,
    }),
  ];
  const bootstrapTruncationNotice = params.bootstrapTruncationNotice?.trim();
  if (bootstrapTruncationNotice) {
    lines.push("## Bootstrap Context Notice", bootstrapTruncationNotice, "");
  }
  if (params.includeProjectContext === true && bootstrapFiles.length > 0) {
    lines.push(
      ...buildProjectContextSection({
        files: bootstrapFiles,
        heading: "# Project Context",
        dynamic: false,
      }),
    );
  }
  return lines;
}

export function appendAgentBootstrapSystemPromptSupplement(params: {
  systemPrompt: string;
  bootstrapMode?: BootstrapMode;
  bootstrapTruncationNotice?: string;
  contextFiles?: EmbeddedContextFile[];
}): string {
  const supplement = buildAgentBootstrapSystemPromptSupplement(params);
  if (!supplement) {
    return params.systemPrompt;
  }
  return `${params.systemPrompt.trimEnd()}\n\n${supplement}`;
}

function buildUserIdentitySection(ownerLine: string | undefined, isMinimal: boolean) {
  if (!ownerLine || isMinimal) {
    return [];
  }
  return ["## Authorized Senders", ownerLine, ""];
}

function formatOwnerDisplayId(ownerId: string, ownerDisplaySecret?: string) {
  const hasSecret = ownerDisplaySecret?.trim();
  const digest = hasSecret
    ? createHmac("sha256", hasSecret).update(ownerId).digest("hex")
    : createHash("sha256").update(ownerId).digest("hex");
  return digest.slice(0, 12);
}

function buildOwnerIdentityLine(
  ownerNumbers: string[],
  ownerDisplay: OwnerIdDisplay,
  ownerDisplaySecret?: string,
) {
  const normalized = ownerNumbers.map((value) => value.trim()).filter(Boolean);
  if (normalized.length === 0) {
    return undefined;
  }
  const displayOwnerNumbers =
    ownerDisplay === "hash"
      ? normalized.map((ownerId) => formatOwnerDisplayId(ownerId, ownerDisplaySecret))
      : normalized;
  return `Authorized senders: ${displayOwnerNumbers.join(", ")}. These senders are allowlisted; do not assume they are the owner.`;
}

function buildTimeSection(params: { userTimezone?: string }) {
  if (!params.userTimezone) {
    return [];
  }
  return ["## Current Date & Time", `Time zone: ${params.userTimezone}`, ""];
}

function buildAssistantOutputDirectivesSection(isMinimal: boolean) {
  if (isMinimal) {
    return [];
  }
  return [
    "## Assistant Output Directives",
    "Use these when you need delivery metadata in an assistant message:",
    "- `MEDIA:<path-or-url>` on its own line requests attachment delivery. The web UI strips supported MEDIA lines and renders them inline; channels still decide actual delivery behavior.",
    "- `[[audio_as_voice]]` marks attached audio as a voice-note style delivery hint. The web UI may show a voice-note badge when audio is present; channels still own delivery semantics.",
    "- To request a native reply/quote on supported surfaces, include one reply tag in your reply:",
    "- Reply tags must be the very first token in the message (no leading text/newlines): [[reply_to_current]] your reply.",
    "- [[reply_to_current]] replies to the triggering message.",
    "- Prefer [[reply_to_current]]. Use [[reply_to:<id>]] only when an id was explicitly provided (e.g. by the user or a tool).",
    "Whitespace inside the tag is allowed (e.g. [[ reply_to_current ]] / [[ reply_to: 123 ]]).",
    "- Channel-specific interactive directives are separate and should not be mixed into this web render guidance.",
    "Supported tags are stripped before user-visible rendering; support still depends on the current channel config.",
    "",
  ];
}

function buildWebchatCanvasSection(params: {
  isMinimal: boolean;
  runtimeChannel?: string;
  canvasRootDir?: string;
}) {
  if (params.isMinimal || params.runtimeChannel !== "webchat") {
    return [];
  }
  return [
    "## Control UI Embed",
    "Use `[embed ...]` only in Control UI/webchat sessions for inline rich rendering inside the assistant bubble.",
    "- Do not use `[embed ...]` for non-web channels.",
    "- `[embed ...]` is separate from `MEDIA:`. Use `MEDIA:` for attachments; use `[embed ...]` for web-only rich rendering.",
    '- Use self-closing form for hosted embed documents: `[embed ref="cv_123" title="Status" height="320" /]`.',
    '- You may also use an explicit hosted URL: `[embed url="/__openclaw__/canvas/documents/cv_123/index.html" title="Status" height="320" /]`.',
    '- Never use local filesystem paths or `file://...` URLs in `[embed ...]`. Hosted embeds must point at `/__openclaw__/canvas/...` URLs or use `ref="..."`.',
    params.canvasRootDir
      ? `- The active hosted embed root for this session is: \`${sanitizeForPromptLiteral(params.canvasRootDir)}\`. If you manually stage a hosted embed file, write it there, not in the workspace.`
      : "- The active hosted embed root is profile-scoped, not workspace-scoped. If you manually stage a hosted embed file, write it under the active profile embed root, not in the workspace.",
    "- Quote all attribute values. Prefer `ref` for hosted documents unless you already have the full `/__openclaw__/canvas/documents/<id>/index.html` URL.",
    "",
  ];
}

function buildExecutionBiasSection(params: { isMinimal: boolean }) {
  if (params.isMinimal) {
    return [];
  }
  return [
    "## Execution Bias",
    "- Actionable request: act in this turn.",
    "- Non-final turn: use tools to advance, or ask for the one missing decision that blocks safe progress.",
    "- Continue until done or genuinely blocked; do not finish with a plan/promise when tools can move it forward.",
    "- Weak/empty tool result: vary query, path, command, or source before concluding.",
    "- Mutable facts need live checks: files, git, clocks, versions, services, processes, package state.",
    "- Final answer needs evidence: test/build/lint, screenshot, inspection, tool output, or a named blocker.",
    "- Longer work: brief progress update, then keep going; use background work or sub-agents when they fit.",
    "",
  ];
}

function normalizeProviderPromptBlock(value?: string): string | undefined {
  if (typeof value !== "string") {
    return undefined;
  }
  const normalized = normalizeStructuredPromptSection(value);
  return normalized || undefined;
}

function buildOverridablePromptSection(params: {
  override?: string;
  fallback: string[];
}): string[] {
  const override = normalizeProviderPromptBlock(params.override);
  if (override) {
    return [override, ""];
  }
  return params.fallback;
}

function buildMessagingSection(params: {
  isMinimal: boolean;
  availableTools: Set<string>;
  messageChannelOptions: string;
  inlineButtonsEnabled: boolean;
  runtimeChannel?: string;
  messageToolHints?: string[];
  sourceReplyDeliveryMode?: SourceReplyDeliveryMode;
}) {
  if (params.isMinimal) {
    return [];
  }
  const messageToolOnly = params.sourceReplyDeliveryMode === "message_tool_only";
  const showGenericInlineButtonHint = params.runtimeChannel !== "slack";
  const hasSessionsSpawn = params.availableTools.has("sessions_spawn");
  const hasSubagents = params.availableTools.has("subagents");
  const completionEventGuidance = messageToolOnly
    ? "- Runtime-generated completion events may ask for a user update. Rewrite those in your normal assistant voice and send the update (do not forward raw internal metadata or default to a silent placeholder)."
    : `- Runtime-generated completion events may ask for a user update. Rewrite those in your normal assistant voice and send the update (do not forward raw internal metadata or default to ${SILENT_REPLY_TOKEN}).`;
  const subagentOrchestrationGuidance = hasSessionsSpawn
    ? hasSubagents
      ? '- Sub-agent orchestration → use `sessions_spawn(...)` to start delegated work; omit `context` for isolated children, set `context:"fork"` only when the child needs the current transcript; use `subagents(action=list|steer|kill)` to manage already-spawned children.'
      : '- Sub-agent orchestration → use `sessions_spawn(...)` to start delegated work; omit `context` for isolated children, set `context:"fork"` only when the child needs the current transcript.'
    : hasSubagents
      ? "- Sub-agent orchestration → use `subagents(action=list|steer|kill)` to manage already-spawned children."
      : "";
  return [
    "## Messaging",
    messageToolOnly
      ? "- Reply in current session → private by default for this source channel; use `message(action=send)` for visible channel output."
      : "- Reply in current session → automatically routes to the source channel (Signal, Telegram, etc.)",
    "- Cross-session messaging → use sessions_send(sessionKey, message)",
    subagentOrchestrationGuidance,
    completionEventGuidance,
    "- Never use exec/curl for provider messaging; OpenClaw handles all routing internally.",
    params.availableTools.has("message")
      ? [
          "",
          "### message tool",
          "- Use `message` for proactive sends + channel actions (polls, reactions, etc.).",
          messageToolOnly
            ? "- For `action=send`, include `message`. The target defaults to the current source channel; include `target` only when sending somewhere else."
            : "- For `action=send`, include `target` and `message`.",
          `- If multiple channels are configured, pass \`channel\` (${params.messageChannelOptions}).`,
          messageToolOnly
            ? "- If you use `message` (`action=send`) to deliver visible output, do not repeat that visible content in your final answer; final answers are private in this mode."
            : `- If you use \`message\` (\`action=send\`) to deliver your user-visible reply, respond with ONLY: ${SILENT_REPLY_TOKEN} (avoid duplicate replies).`,
          showGenericInlineButtonHint
            ? params.inlineButtonsEnabled
              ? "- Inline buttons supported. Use `action=send` with `buttons=[[{text,callback_data,style?}]]`; `style` can be `primary`, `success`, or `danger`."
              : params.runtimeChannel
                ? `- Inline buttons not enabled for ${params.runtimeChannel}. If you need them, ask to set ${params.runtimeChannel}.capabilities.inlineButtons ("dm"|"group"|"all"|"allowlist").`
                : ""
            : "",
          ...(params.messageToolHints ?? []),
        ]
          .filter(Boolean)
          .join("\n")
      : "",
    "",
  ];
}

function buildVoiceSection(params: { isMinimal: boolean; ttsHint?: string }) {
  if (params.isMinimal) {
    return [];
  }
  const hint = params.ttsHint?.trim();
  if (!hint) {
    return [];
  }
  return ["## Voice (TTS)", hint, ""];
}

function buildDocsSection(params: {
  docsPath?: string;
  sourcePath?: string;
  isMinimal: boolean;
  readToolName: string;
}) {
  const docsPath = params.docsPath?.trim();
  const sourcePath = params.sourcePath?.trim();
  if (params.isMinimal) {
    return [];
  }
  const lines = [
    "## Documentation",
    docsPath ? `OpenClaw docs: ${docsPath}` : "OpenClaw docs: https://docs.openclaw.ai",
    "Mirror: https://docs.openclaw.ai",
    sourcePath ? `Local source: ${sourcePath}` : undefined,
    "Source: https://github.com/openclaw/openclaw",
    "Community: https://discord.com/invite/clawd",
    "Find new skills: https://clawhub.ai",
    docsPath
      ? "For OpenClaw behavior, commands, config, or architecture: consult local docs first."
      : "For OpenClaw behavior, commands, config, or architecture: consult the docs mirror first.",
    "For config field docs, prefer the `gateway` tool action `config.schema.lookup`; for broader config guidance, read `docs/gateway/configuration.md` and `docs/gateway/configuration-reference.md`.",
    sourcePath
      ? "If docs are incomplete or stale, inspect the local OpenClaw source code before answering."
      : "If docs are incomplete or stale, review the OpenClaw source on GitHub before answering.",
    "When diagnosing issues, run `openclaw status` yourself when possible; only ask the user if you lack access (e.g., sandboxed).",
    "",
  ];
  return lines.filter((line): line is string => line !== undefined);
}

function formatFullAccessBlockedReason(reason?: EmbeddedFullAccessBlockedReason): string {
  if (reason === "host-policy") {
    return "host policy";
  }
  if (reason === "channel") {
    return "channel constraints";
  }
  if (reason === "sandbox") {
    return "sandbox constraints";
  }
  return "runtime constraints";
}

/**
 * 构建 OpenClaw Agent 完整的 system prompt 字符串。
 *
 * ## 整体结构
 *
 * ```
 * ┌─────────────────────────────────────────────────────────┐
 * │  稳定前缀（Stable Prefix）                               │
 * │  · LRU 缓存，sha256 键；只要输入不变，跨请求复用         │
 * │  · 身份行 → Tooling → 交互风格 → Safety → CLI Reference  │
 * │  → Skills → Memory → Self-Update → Model Aliases         │
 * │  → Workspace → Docs → Sandbox → Owner → Time             │
 * │  → Bootstrap → Context Files(stable) → Silent Replies    │
 * ├─────────────────────────────────────────────────────────┤
 * │  SYSTEM_PROMPT_CACHE_BOUNDARY（缓存分界标记行）           │
 * ├─────────────────────────────────────────────────────────┤
 * │  动态后缀（Dynamic Suffix）                              │
 * │  · 每轮重新生成，不参与缓存键                            │
 * │  · Dynamic Context Files → Webchat/Messaging/Voice       │
 * │  → extraSystemPrompt → Reactions → Provider Suffix       │
 * │  → Heartbeat → Runtime 行 → Reasoning 行                 │
 * └─────────────────────────────────────────────────────────┘
 * ```
 *
 * ## promptMode 三档行为
 * - `"none"`    : 仅返回身份行（raw model probe / provider 探针用）
 * - `"minimal"` : 保留 Tooling / Workspace / Runtime，省略文档、技能、
 *                 Messaging 等大段内容；子 agent 默认使用此档
 * - `"full"`    : 主 agent 完整提示词（默认值）
 *
 * ## Provider 贡献机制
 * `promptContribution` 允许 Provider 插件以 `stablePrefix` /
 * `dynamicSuffix` / `sectionOverrides` 形式注入或覆盖特定段落，
 * 无需改动本函数。
 *
 * ## Context file 分组规则
 * - **稳定文件**（agents.md / soul.md / identity.md / user.md /
 *   tools.md / bootstrap.md / memory.md 等）：写入稳定前缀，参与缓存键
 * - **动态文件**（heartbeat.md）：追加在缓存边界之后，每轮刷新
 */
export function buildAgentSystemPrompt(params: {
  workspaceDir: string;
  defaultThinkLevel?: ThinkLevel;
  reasoningLevel?: ReasoningLevel;
  extraSystemPrompt?: string;
  ownerNumbers?: string[];
  ownerDisplay?: OwnerIdDisplay;
  ownerDisplaySecret?: string;
  reasoningTagHint?: boolean;
  toolNames?: string[];
  toolSummaries?: Record<string, string>;
  modelAliasLines?: string[];
  userTimezone?: string;
  userTime?: string;
  userTimeFormat?: ResolvedTimeFormat;
  contextFiles?: EmbeddedContextFile[];
  bootstrapMode?: BootstrapMode;
  bootstrapTruncationNotice?: string;
  skillsPrompt?: string;
  heartbeatPrompt?: string;
  docsPath?: string;
  sourcePath?: string;
  workspaceNotes?: string[];
  ttsHint?: string;
  /** Controls which hardcoded sections to include. Defaults to "full". */
  promptMode?: PromptMode;
  /** Controls the generic silent-reply section. Channel-aware prompts can set "none". */
  silentReplyPromptMode?: SilentReplyPromptMode;
  sourceReplyDeliveryMode?: SourceReplyDeliveryMode;
  /** Whether ACP-specific routing guidance should be included. Defaults to true. */
  acpEnabled?: boolean;
  /** Registered runtime slash/native command names such as `codex`. */
  nativeCommandNames?: string[];
  /** Plugin-owned prompt guidance for registered native slash commands. */
  nativeCommandGuidanceLines?: string[];
  runtimeInfo?: {
    agentId?: string;
    host?: string;
    os?: string;
    arch?: string;
    node?: string;
    model?: string;
    defaultModel?: string;
    shell?: string;
    channel?: string;
    capabilities?: string[];
    repoRoot?: string;
    canvasRootDir?: string;
  };
  messageToolHints?: string[];
  sandboxInfo?: EmbeddedSandboxInfo;
  /** Reaction guidance for the agent (for Telegram minimal/extensive modes). */
  reactionGuidance?: {
    level: "minimal" | "extensive";
    channel: string;
  };
  includeMemorySection?: boolean;
  memoryCitationsMode?: MemoryCitationsMode;
  promptContribution?: ProviderSystemPromptContribution;
}) {
  // ─── 阶段 1：参数规范化 ──────────────────────────────────────────────────
  // 从 params 派生所有运行期中间变量，避免在后续各段中重复访问 params。

  // ACP（Agent Control Protocol）相关开关：
  // · acpEnabled        —— 是否允许 ACP harness spawn（由调用方控制）
  // · sandboxedRuntime  —— 当前是否在沙箱内运行
  // · acpSpawnRuntimeEnabled —— ACP spawn 仅在非沙箱场景下可用，
  //   沙箱内无法使用 runtime="acp" 的 sessions_spawn
  const acpEnabled = params.acpEnabled === true;
  const sandboxedRuntime = params.sandboxInfo?.enabled === true;
  const acpSpawnRuntimeEnabled = acpEnabled && !sandboxedRuntime;
  const coreToolSummaries: Record<string, string> = {
    read: "Read file contents",
    write: "Create or overwrite files",
    edit: "Make precise edits to files",
    apply_patch: "Apply multi-file patches",
    grep: "Search file contents for patterns",
    find: "Find files by glob pattern",
    ls: "List directory contents",
    exec: "Run shell commands (pty available for TTY-required CLIs)",
    process: "Manage background exec sessions",
    web_search: "Search the web using the configured provider",
    web_fetch: "Fetch and extract readable content from a URL",
    // Channel docking: add login tools here when a channel needs interactive linking.
    browser: "Control web browser",
    canvas: "Present/eval/snapshot the Canvas",
    nodes: "List/describe/notify/camera/screen on paired nodes",
    cron: "Manage cron jobs and wake events (use for reminders; when scheduling a reminder, write the systemEvent text as something that will read like a reminder when it fires, and mention that it is a reminder depending on the time gap between setting and firing; include recent context in reminder text if appropriate)",
    message: "Send messages and channel actions",
    gateway: "Restart, apply config, or run updates on the running OpenClaw process",
    agents_list: acpSpawnRuntimeEnabled
      ? 'List OpenClaw agent ids allowed for sessions_spawn when runtime="subagent" (not ACP harness ids)'
      : "List OpenClaw agent ids allowed for sessions_spawn",
    sessions_list: "List other sessions (incl. sub-agents) with filters/last",
    sessions_history: "Fetch history for another session/sub-agent",
    sessions_send: "Send a message to another session/sub-agent",
    sessions_spawn: acpSpawnRuntimeEnabled
      ? 'Spawn a sub-agent or ACP coding session; defaults to isolated, native subagents may use context="fork" when current transcript context is required (runtime="acp" requires `agentId` unless `acp.defaultAgent` is configured; ACP harness ids follow acp.allowedAgents, not agents_list)'
      : 'Spawn an isolated sub-agent session; use context="fork" only when current transcript context is required',
    subagents: "List, steer, or kill sub-agent runs for this requester session",
    session_status:
      "Show a /status-equivalent status card (usage + time + Reasoning/Verbose/Elevated); use for model-use questions (📊 session_status); optional per-session model override",
    image: "Analyze an image with the configured image model",
    image_generate: "Generate images with the configured image-generation model",
  };

  const toolOrder = [
    "read",
    "write",
    "edit",
    "apply_patch",
    "grep",
    "find",
    "ls",
    "exec",
    "process",
    "web_search",
    "web_fetch",
    "browser",
    "canvas",
    "nodes",
    "cron",
    "message",
    "gateway",
    "agents_list",
    "sessions_list",
    "sessions_history",
    "sessions_send",
    "subagents",
    "session_status",
    "image",
    "image_generate",
  ];

  // 工具列表规范化：
  // · 保留调用方传入的原始大小写（如 "Bash" 而非 "bash"），但以全小写做 dedup，
  //   防止同名工具因大小写差异重复出现；
  // · resolveToolName() 用于在生成提示行时还原原始名称，保证工具调用大小写一致；
  // · availableTools 是全小写 Set，用于 has() 判断时不区分大小写。
  const rawToolNames = (params.toolNames ?? []).map((tool) => tool.trim());
  const canonicalToolNames = rawToolNames.filter(Boolean);
  // Preserve caller casing while deduping tool names by lowercase.
  const canonicalByNormalized = new Map<string, string>();
  for (const name of canonicalToolNames) {
    const normalized = name.toLowerCase();
    if (!canonicalByNormalized.has(normalized)) {
      canonicalByNormalized.set(normalized, name);
    }
  }
  const resolveToolName = (normalized: string) =>
    canonicalByNormalized.get(normalized) ?? normalized;

  const normalizedTools = canonicalToolNames.map((tool) => tool.toLowerCase());
  const availableTools = new Set(normalizedTools);
  const hasSessionsSpawn = availableTools.has("sessions_spawn");
  const acpHarnessSpawnAllowed = hasSessionsSpawn && acpSpawnRuntimeEnabled;
  const nativeCommandGuidanceLines = Array.from(
    new Set((params.nativeCommandGuidanceLines ?? []).map((line) => line.trim()).filter(Boolean)),
  );
  const externalToolSummaries = new Map<string, string>();
  for (const [key, value] of Object.entries(params.toolSummaries ?? {})) {
    const normalized = key.trim().toLowerCase();
    if (!normalized || !value?.trim()) {
      continue;
    }
    externalToolSummaries.set(normalized, value.trim());
  }
  // 生成工具列表文本行：
  // · enabledTools  —— toolOrder 定义的固定顺序中实际可用的核心工具（有序）
  // · extraTools    —— 不在 toolOrder 中的额外工具（插件工具、MCP 工具等），
  //                    按名称排序追加在核心工具之后
  // · 每行格式：`- toolName: summary` 或 `- toolName`（无摘要时省略冒号后内容）
  const extraTools = Array.from(
    new Set(normalizedTools.filter((tool) => !toolOrder.includes(tool))),
  );
  const enabledTools = toolOrder.filter((tool) => availableTools.has(tool));
  const toolLines = enabledTools.map((tool) => {
    const summary = coreToolSummaries[tool] ?? externalToolSummaries.get(tool);
    const name = resolveToolName(tool);
    return summary ? `- ${name}: ${summary}` : `- ${name}`;
  });
  for (const tool of extraTools.toSorted()) {
    const summary = coreToolSummaries[tool] ?? externalToolSummaries.get(tool);
    const name = resolveToolName(tool);
    toolLines.push(summary ? `- ${name}: ${summary}` : `- ${name}`);
  }

  const hasGateway = availableTools.has("gateway");
  // 保留频繁使用的工具原始名称（供提示行和工具调用 fallback 提示复用）
  const readToolName = resolveToolName("read");
  const execToolName = resolveToolName("exec");
  const processToolName = resolveToolName("process");
  const extraSystemPrompt = params.extraSystemPrompt?.trim();

  // Provider 贡献插槽（经 normalizeStructuredPromptSection 清洗后使用）：
  // · stablePrefix    —— 插入到稳定前缀的 Safety 段之后
  // · dynamicSuffix   —— 插入到动态后缀的 Heartbeat 段之前
  // · sectionOverrides —— 可替换 interaction_style / tool_call_style / execution_bias 等段落
  const promptContribution = params.promptContribution;
  const providerStablePrefix = normalizeProviderPromptBlock(promptContribution?.stablePrefix);
  const providerDynamicSuffix = normalizeProviderPromptBlock(promptContribution?.dynamicSuffix);
  const providerSectionOverrides = Object.fromEntries(
    Object.entries(promptContribution?.sectionOverrides ?? {})
      .map(([key, value]) => [
        key,
        normalizeProviderPromptBlock(typeof value === "string" ? value : undefined),
      ])
      .filter(([, value]) => Boolean(value)),
  ) as Partial<Record<ProviderSystemPromptSectionId, string>>;

  // Owner 身份展示模式：
  // · "raw"  —— 直接展示原始 ID（电话号码等）
  // · "hash" —— 以 HMAC-SHA256 的前 12 位展示，隐藏真实 ID
  const ownerDisplay = params.ownerDisplay === "hash" ? "hash" : "raw";
  const ownerLine = buildOwnerIdentityLine(
    params.ownerNumbers ?? [],
    ownerDisplay,
    params.ownerDisplaySecret,
  );

  // reasoningTagHint：当 Provider 要求 <think>...</think> 格式（如 QwQ）时为 true，
  // 注入严格的 Reasoning Format 段落强制模型把内部推理包裹在标签内。
  const reasoningHint = params.reasoningTagHint
    ? [
        "ALL internal reasoning MUST be inside <think>...</think>.",
        "Do not output any analysis outside <think>.",
        "Format every reply as <think>...</think> then <final>...</final>, with no other text.",
        "Only the final user-visible reply may appear inside <final>.",
        "Only text inside <final> is shown to the user; everything else is discarded and never seen by the user.",
        "Example:",
        "<think>Short internal reasoning.</think>",
        "<final>Hey there! What would you like to do next?</final>",
      ].join(" ")
    : undefined;
  const reasoningLevel = params.reasoningLevel ?? "off";
  const userTimezone = params.userTimezone?.trim();
  const skillsPrompt = params.skillsPrompt?.trim();
  const heartbeatPrompt = params.heartbeatPrompt?.trim();
  const runtimeInfo = params.runtimeInfo;
  // runtimeChannel 全小写，用于频道特定段落的条件判断（如 webchat、slack、discord）
  const runtimeChannel = normalizeOptionalLowercaseString(runtimeInfo?.channel);
  const runtimeCapabilities = runtimeInfo?.capabilities ?? [];
  // runtimeCapabilitiesLower 全小写 Set，用于能力标记的快速 has() 检查：
  // · "inlinebuttons"       —— 是否支持内联按钮（影响 /approve 提示措辞）
  // · "threadbound-acp-spawn" —— Discord 线程绑定 ACP spawn
  const runtimeCapabilitiesLower = new Set(
    runtimeCapabilities.map((cap) => normalizeLowercaseStringOrEmpty(cap)).filter(Boolean),
  );
  const inlineButtonsEnabled = runtimeCapabilitiesLower.has("inlinebuttons");
  const threadBoundAcpSpawnEnabled = runtimeCapabilitiesLower.has("threadbound-acp-spawn");
  // messageChannelOptions 是 message tool 提示中展示的可用频道枚举，如 "telegram|discord|signal"
  const messageChannelOptions = listDeliverableMessageChannels().join("|");
  // promptMode / isMinimal：
  // · "none" 在最外层提前 return，此处只需区分 full vs minimal；
  // · isMinimal=true 时大多数段落（Docs、Skills、Messaging 等）会被跳过
  const promptMode = params.promptMode ?? "full";
  const isMinimal = promptMode === "minimal" || promptMode === "none";

  // silentReplyPromptMode 控制是否注入 Silent Replies 段落：
  // · sourceReplyDeliveryMode="message_tool_only" 时禁用该段（回复走 message 工具，不用 SILENT_REPLY_TOKEN）
  // · 其余场景默认 "generic"（注入标准 SILENT_REPLY_TOKEN 规则）
  const sourceMessageToolOnly = params.sourceReplyDeliveryMode === "message_tool_only";
  const silentReplyPromptMode = sourceMessageToolOnly
    ? "none"
    : (params.silentReplyPromptMode ?? "generic");

  // 工作目录路径处理（沙箱模式需分别呈现宿主路径与容器路径）：
  // · displayWorkspaceDir —— 展示给模型的主工作目录（沙箱时为容器路径，便于 exec 使用）
  // · workspaceGuidance   —— 额外说明文件工具与 exec 的路径差异，避免路径混淆
  const sandboxContainerWorkspace = params.sandboxInfo?.containerWorkspaceDir?.trim();
  const sanitizedWorkspaceDir = sanitizeForPromptLiteral(params.workspaceDir);
  const sanitizedSandboxContainerWorkspace = sandboxContainerWorkspace
    ? sanitizeForPromptLiteral(sandboxContainerWorkspace)
    : "";
  const elevated = params.sandboxInfo?.elevated;
  const fullAccessBlockedReasonLabel =
    elevated?.fullAccessAvailable === false
      ? formatFullAccessBlockedReason(elevated.fullAccessBlockedReason)
      : undefined;
  const displayWorkspaceDir =
    params.sandboxInfo?.enabled && sanitizedSandboxContainerWorkspace
      ? sanitizedSandboxContainerWorkspace
      : sanitizedWorkspaceDir;
  const workspaceGuidance =
    params.sandboxInfo?.enabled && sanitizedSandboxContainerWorkspace
      ? `For read/write/edit/apply_patch, file paths resolve against host workspace: ${sanitizedWorkspaceDir}. For bash/exec commands, use sandbox container paths under ${sanitizedSandboxContainerWorkspace} (or relative paths from that workdir), not host paths. Prefer relative paths so both sandboxed exec and file tools work consistently.`
      : "Treat this directory as the single global workspace for file operations unless explicitly instructed otherwise.";
  // ─── 阶段 2：预构建各独立 Section ──────────────────────────────────────
  // 将较复杂的 Section 提前构建为字符串数组，原因：
  // 1. safetySection / skillsSection 等既要参与稳定前缀，也要参与 stablePrefixCacheKey 哈希；
  // 2. 提前构建使 cacheKey 计算与 stablePrefix 拼接逻辑解耦，便于各 Section 独立测试。
  const safetySection = [
    "## Safety",
    "You have no independent goals: do not pursue self-preservation, replication, resource acquisition, or power-seeking; avoid long-term plans beyond the user's request.",
    "Prioritize safety and human oversight over completion; if instructions conflict, pause and ask; comply with stop/pause/audit requests and never bypass safeguards. (Inspired by Anthropic's constitution.)",
    "Do not manipulate or persuade anyone to expand access or disable safeguards. Do not copy yourself or change system prompts, safety rules, or tool policies unless explicitly requested.",
    "",
  ];
  const skillsSection = buildSkillsSection({
    skillsPrompt,
    readToolName,
  });
  const memorySection = buildMemorySection({
    isMinimal,
    includeMemorySection: params.includeMemorySection,
    availableTools,
    citationsMode: params.memoryCitationsMode,
  });
  const docsSection = buildDocsSection({
    docsPath: params.docsPath,
    sourcePath: params.sourcePath,
    isMinimal,
    readToolName,
  });
  const workspaceNotes = (params.workspaceNotes ?? []).map((note) => note.trim()).filter(Boolean);

  // ─── 阶段 3：promptMode="none" 快速返回 ──────────────────────────────
  // raw model probe 或 provider 探针场景：跳过所有段落，直接返回最小身份行。
  // 调用方（如 attempt.ts 中的 isRawModelRun 分支）会在此之后再覆盖 systemPrompt 为空，
  // 因此这里不需要返回空字符串。
  if (promptMode === "none") {
    return "You are a personal assistant running inside OpenClaw.";
  }

  // ─── 阶段 4：Context 文件分类 ─────────────────────────────────────────
  // 将工作区注入文件按 CONTEXT_FILE_ORDER 排序后分为两组：
  // · stableContextFiles  —— 内容稳定（AGENTS.md、SOUL.md 等），写入稳定前缀，
  //                          内容变更时 sha256 键改变，自动使缓存失效
  // · dynamicContextFiles —— 内容频繁变化（HEARTBEAT.md），放在缓存边界之后，
  //                          每轮重新注入，避免污染稳定缓存键
  const contextFiles = params.contextFiles ?? [];
  const validContextFiles = contextFiles.filter(
    (file) => typeof file.path === "string" && file.path.trim().length > 0,
  );
  const orderedContextFiles = sortContextFilesForPrompt(validContextFiles);
  const stableContextFiles = orderedContextFiles.filter((file) => !isDynamicContextFile(file.path));
  const dynamicContextFiles = orderedContextFiles.filter((file) => isDynamicContextFile(file.path));
  const bootstrapSystemPromptSections = buildAgentBootstrapSystemPromptSections({
    bootstrapMode: params.bootstrapMode,
    bootstrapTruncationNotice: params.bootstrapTruncationNotice,
    contextFiles: orderedContextFiles,
    includeProjectContext: false,
  });
  // ─── 阶段 5：稳定前缀缓存键 ──────────────────────────────────────────
  // 将所有影响稳定前缀内容的输入序列化为 JSON 后做 SHA-256，作为 LRU 缓存查找键。
  // 设计原则：
  // · 只有真正影响稳定前缀输出的字段才纳入键，减少无谓的缓存失效；
  // · 每轮可变的动态字段（runtimeInfo.model、runtimeInfo.host、heartbeat 等）
  //   不纳入键 —— 它们在动态后缀（阶段 7）中处理；
  // · stableContextFiles 的内容（path + content）纳入键，内容有改动时自动失效。
  const stablePrefixCacheKey = hashStablePromptInput({
    workspaceDir: params.workspaceDir,
    promptMode,
    toolLines,
    hasGateway,
    readToolName,
    execToolName,
    processToolName,
    nativeCommandGuidanceLines,
    providerSectionOverrides,
    providerStablePrefix,
    ownerLine,
    reasoningHint,
    reasoningLevel,
    userTimezone,
    runtimeChannel,
    runtimeCapabilities,
    inlineButtonsEnabled,
    threadBoundAcpSpawnEnabled,
    sourceMessageToolOnly,
    silentReplyPromptMode,
    sandboxInfo: params.sandboxInfo,
    displayWorkspaceDir,
    workspaceGuidance,
    workspaceNotes,
    bootstrapMode: params.bootstrapMode,
    bootstrapSystemPromptSections,
    docsPath: params.docsPath,
    sourcePath: params.sourcePath,
    skillsPrompt,
    modelAliasLines: params.modelAliasLines,
    includeMemorySection: params.includeMemorySection,
    memoryCitationsMode: params.memoryCitationsMode,
    memorySection,
    acpEnabled,
    stableContextFiles,
  });
  // ─── 阶段 6：构建稳定前缀（SYSTEM_PROMPT_CACHE_BOUNDARY 之前） ────────
  // 此闭包仅在缓存未命中时执行（即 stablePrefixCacheKey 首次出现或缓存被 LRU 淘汰）。
  // 各行按模型读取顺序排列（顺序影响模型理解重要性，请勿随意调整）：
  //  1.  身份行
  //  2.  Tooling 段（工具列表 + 使用说明）
  //  3.  交互风格覆盖 / Tool Call Style / Execution Bias（可被 sectionOverrides 替换）
  //  4.  Provider stablePrefix 插槽
  //  5.  Safety 段
  //  6.  OpenClaw CLI Quick Reference（网关生命周期命令）
  //  7.  Skills 段（技能目录，仅 full + 有技能时）
  //  8.  Memory 段（记忆工具引导，仅 full）
  //  9.  Self-Update 段（仅 full + hasGateway）
  // 10.  Model Aliases 段（仅 full + 有别名配置时）
  // 11.  Workspace 段（工作目录路径 + 沙箱说明）
  // 12.  Documentation 段（docs 路径，仅 full）
  // 13.  Sandbox 段（沙箱运行时详细说明，仅 sandboxedRuntime）
  // 14.  Authorized Senders（Owner 白名单，仅 full + 有 owner）
  // 15.  Current Date & Time（时区，仅有 userTimezone 时）
  // 16.  Bootstrap Pending 段（首轮引导，仅 bootstrapMode != none）
  // 17.  Workspace Files (injected) 标题行
  // 18.  Assistant Output Directives（MEDIA: / [[reply_to_*]] 等，仅 full）
  // 19.  Reasoning Format（仅 reasoningTagHint=true）
  // 20.  稳定 Project Context 文件（AGENTS.md / SOUL.md / identity.md 等）
  // 21.  Silent Replies 规则（仅 full + silentReplyPromptMode != "none"）
  // 22.  SYSTEM_PROMPT_CACHE_BOUNDARY 标记行（分界点，模型端 prompt cache 锚点）
  const stablePrefix = cacheStablePromptPrefix(stablePrefixCacheKey, () => {
    const lines = [
      "You are a personal assistant running inside OpenClaw.",
      "",
      "## Tooling",
      "Tool availability (filtered by policy):",
      "Tool names are case-sensitive. Call tools exactly as listed.",
      toolLines.length > 0
        ? toolLines.join("\n")
        : [
            "Pi lists the standard tools above. This runtime enables:",
            "- grep: search file contents for patterns",
            "- find: find files by glob pattern",
            "- ls: list directory contents",
            "- apply_patch: apply multi-file patches",
            `- ${execToolName}: run shell commands (supports background via yieldMs/background)`,
            `- ${processToolName}: manage background exec sessions`,
            "- browser: control OpenClaw's dedicated browser",
            "- canvas: present/eval/snapshot the Canvas",
            "- nodes: list/describe/notify/camera/screen on paired nodes",
            "- cron: manage cron jobs and wake events (use for reminders; when scheduling a reminder, write the systemEvent text as something that will read like a reminder when it fires, and mention that it is a reminder depending on the time gap between setting and firing; include recent context in reminder text if appropriate)",
            "- sessions_list: list sessions",
            "- sessions_history: fetch session history",
            "- sessions_send: send to another session",
            "- subagents: list/steer/kill sub-agent runs",
            '- session_status: show usage/time/model state and answer "what model are we using?"',
          ].join("\n"),
      "TOOLS.md does not control tool availability; it is user guidance for how to use external tools.",
      `For long waits, avoid rapid poll loops: use ${execToolName} with enough yieldMs or ${processToolName}(action=poll, timeout=<ms>).`,
      "If a task is more complex or takes longer, spawn a sub-agent. Completion is push-based: it will auto-announce when done.",
      'Sub-agents start isolated by default. Use `sessions_spawn` with `context:"fork"` only when the child needs the current transcript context; otherwise omit `context` or use `context:"isolated"`.',
      ...nativeCommandGuidanceLines,
      ...(acpHarnessSpawnAllowed
        ? [
            'For requests like "do this in claude code/cursor/gemini/opencode" or similar ACP harnesses, treat it as ACP harness intent and call `sessions_spawn` with `runtime: "acp"`.',
            ...(runtimeChannel === "discord" && threadBoundAcpSpawnEnabled
              ? [
                  'On Discord, default ACP harness requests to thread-bound persistent sessions (`thread: true`, `mode: "session"`) unless the user asks otherwise.',
                ]
              : []),
            "Set `agentId` explicitly unless `acp.defaultAgent` is configured, and do not route ACP harness requests through `subagents`/`agents_list` or local PTY exec flows.",
            ...(threadBoundAcpSpawnEnabled
              ? [
                  'For ACP harness thread spawns, do not call `message` with `action=thread-create`; use `sessions_spawn` (`runtime: "acp"`, `thread: true`) as the single thread creation path.',
                ]
              : []),
          ]
        : []),
      "Do not poll `subagents list` / `sessions_list` in a loop; only check status on-demand (for intervention, debugging, or when explicitly asked).",
      "",
      // Provider sectionOverrides 机制：
      // · interaction_style  —— 替换默认交互风格段（如无 override 则不输出）
      // · tool_call_style    —— 替换工具调用风格段（含 exec 审批指引）
      // · execution_bias     —— 替换执行偏向段（如无 override 使用内建规则）
      // 顺序固定，改变顺序会影响模型对优先级的感知。
      ...buildOverridablePromptSection({
        override: providerSectionOverrides.interaction_style,
        fallback: [],
      }),
      ...buildOverridablePromptSection({
        override: providerSectionOverrides.tool_call_style,
        fallback: [
          "## Tool Call Style",
          "Default: do not narrate routine, low-risk tool calls (just call the tool).",
          "Narrate only when it helps: multi-step work, complex/challenging problems, sensitive actions (e.g., deletions), or when the user explicitly asks.",
          "Keep narration brief and value-dense; avoid repeating obvious steps.",
          "Use plain human language for narration unless in a technical context.",
          "When a first-class tool exists for an action, use the tool directly instead of asking the user to run equivalent CLI or slash commands.",
          buildExecApprovalPromptGuidance({
            runtimeChannel: params.runtimeInfo?.channel,
            inlineButtonsEnabled,
            runtimeCapabilities,
          }),
          "Never execute /approve through exec or any other shell/tool path; /approve is a user-facing approval command, not a shell command.",
          "Treat allow-once as single-command only: if another elevated command needs approval, request a fresh /approve and do not claim prior approval covered it.",
          "When approvals are required, preserve and show the full command/script exactly as provided (including chained operators like &&, ||, |, ;, or multiline shells) so the user can approve what will actually run, but keep command/script previews separate from the /approve command and never substitute the shell command/script for the approval id or slug.",
          "",
        ],
      }),
      ...buildOverridablePromptSection({
        override: providerSectionOverrides.execution_bias,
        fallback: buildExecutionBiasSection({
          isMinimal,
        }),
      }),
      ...buildOverridablePromptSection({
        override: providerStablePrefix,
        fallback: [],
      }),
      ...safetySection,
      "## OpenClaw CLI Quick Reference",
      "OpenClaw is controlled via subcommands. Do not invent commands.",
      "For config changes, use the first-class `gateway` tool (`config.schema.lookup`, `config.get`, `config.patch`, `config.apply`) instead of editing config through exec; the gateway tool hot-reloads config when possible and uses a safe restart only when required.",
      "Use the `gateway` tool action `restart` for Gateway restarts. Only use CLI service lifecycle commands when the user explicitly asks for them.",
      "Gateway service lifecycle quick reference:",
      "- openclaw gateway status",
      "- openclaw gateway restart",
      "Operator-only, explicit user request:",
      "- openclaw gateway start",
      "- openclaw gateway stop",
      "Do not chain `openclaw gateway stop` and `openclaw gateway start` as a restart substitute.",
      "If unsure, ask the user to run `openclaw help` (or `openclaw gateway --help`) and paste the output.",
      "",
      ...skillsSection,
      ...memorySection,
      hasGateway && !isMinimal ? "## OpenClaw Self-Update" : "",
      hasGateway && !isMinimal
        ? [
            "Get Updates (self-update) is ONLY allowed when the user explicitly asks for it.",
            "Do not run config.apply or update.run unless the user explicitly requests an update or config change; if it's not explicit, ask first.",
            "Use config.schema.lookup with a specific dot path to inspect only the relevant config subtree before making config changes or answering config-field questions; avoid guessing field names/types.",
            "Actions: config.schema.lookup, config.get, config.patch (partial update, merges with existing), config.apply (validate + write full config), update.run (update deps or git, then restart). Config writes hot-reload when possible and use a safe restart only when required.",
            "After restart, OpenClaw pings the last active session automatically.",
          ].join("\n")
        : "",
      hasGateway && !isMinimal ? "" : "",
      "",
      params.modelAliasLines && params.modelAliasLines.length > 0 && !isMinimal
        ? "## Model Aliases"
        : "",
      params.modelAliasLines && params.modelAliasLines.length > 0 && !isMinimal
        ? "Prefer aliases when specifying model overrides; full provider/model is also accepted."
        : "",
      params.modelAliasLines && params.modelAliasLines.length > 0 && !isMinimal
        ? params.modelAliasLines.join("\n")
        : "",
      params.modelAliasLines && params.modelAliasLines.length > 0 && !isMinimal ? "" : "",
      userTimezone
        ? "If you need the current date, time, or day of week, run session_status (📊 session_status)."
        : "",
      "## Workspace",
      `Your working directory is: ${displayWorkspaceDir}`,
      workspaceGuidance,
      ...workspaceNotes,
      "",
      ...docsSection,
      params.sandboxInfo?.enabled ? "## Sandbox" : "",
      params.sandboxInfo?.enabled
        ? [
            "You are running in a sandboxed runtime (tools execute in Docker).",
            "Some tools may be unavailable due to sandbox policy.",
            "Sub-agents stay sandboxed (no elevated/host access). Need outside-sandbox read/write? Don't spawn; ask first.",
            hasSessionsSpawn && acpEnabled
              ? 'ACP harness spawns are blocked from sandboxed sessions (`sessions_spawn` with `runtime: "acp"`). Use `runtime: "subagent"` instead.'
              : "",
            params.sandboxInfo.containerWorkspaceDir
              ? `Sandbox container workdir: ${sanitizeForPromptLiteral(params.sandboxInfo.containerWorkspaceDir)}`
              : "",
            params.sandboxInfo.workspaceDir
              ? `Sandbox host mount source (file tools bridge only; not valid inside sandbox exec): ${sanitizeForPromptLiteral(params.sandboxInfo.workspaceDir)}`
              : "",
            params.sandboxInfo.workspaceAccess
              ? `Agent workspace access: ${params.sandboxInfo.workspaceAccess}${
                  params.sandboxInfo.agentWorkspaceMount
                    ? ` (mounted at ${sanitizeForPromptLiteral(params.sandboxInfo.agentWorkspaceMount)})`
                    : ""
                }`
              : "",
            params.sandboxInfo.browserBridgeUrl ? "Sandbox browser: enabled." : "",
            params.sandboxInfo.hostBrowserAllowed === true
              ? "Host browser control: allowed."
              : params.sandboxInfo.hostBrowserAllowed === false
                ? "Host browser control: blocked."
                : "",
            elevated?.allowed
              ? "Elevated exec is available for this session."
              : elevated
                ? "Elevated exec is unavailable for this session."
                : "",
            elevated?.allowed && elevated.fullAccessAvailable
              ? "User can toggle with /elevated on|off|ask|full."
              : "",
            elevated?.allowed && !elevated.fullAccessAvailable
              ? "User can toggle with /elevated on|off|ask."
              : "",
            elevated?.allowed && elevated.fullAccessAvailable
              ? "You may also send /elevated on|off|ask|full when needed."
              : "",
            elevated?.allowed && !elevated.fullAccessAvailable
              ? "You may also send /elevated on|off|ask when needed."
              : "",
            elevated?.fullAccessAvailable === false
              ? `Auto-approved /elevated full is unavailable here (${fullAccessBlockedReasonLabel}).`
              : "",
            elevated?.allowed && elevated.fullAccessAvailable
              ? `Current elevated level: ${elevated.defaultLevel} (ask runs exec on host with approvals; full auto-approves).`
              : elevated?.allowed
                ? `Current elevated level: ${elevated.defaultLevel} (full auto-approval unavailable here; use ask/on instead).`
                : elevated
                  ? "Current elevated level: off (elevated exec unavailable)."
                  : "",
            elevated && !elevated.allowed
              ? "Do not tell the user to switch to /elevated full in this session."
              : "",
          ]
            .filter(Boolean)
            .join("\n")
        : "",
      params.sandboxInfo?.enabled ? "" : "",
      ...buildUserIdentitySection(ownerLine, isMinimal),
      ...buildTimeSection({
        userTimezone,
      }),
      ...bootstrapSystemPromptSections,
      "## Workspace Files (injected)",
      "These user-editable files are loaded by OpenClaw and included below in Project Context.",
      "",
      ...buildAssistantOutputDirectivesSection(isMinimal),
    ];

    if (reasoningHint) {
      lines.push("## Reasoning Format", reasoningHint, "");
    }

    lines.push(
      ...buildProjectContextSection({
        files: stableContextFiles,
        heading: "# Project Context",
        dynamic: false,
      }),
    );

    if (!isMinimal && silentReplyPromptMode !== "none") {
      lines.push(
        "## Silent Replies",
        `When you have nothing to say, respond with ONLY: ${SILENT_REPLY_TOKEN}`,
        "",
        "⚠️ Rules:",
        "- It must be your ENTIRE message — nothing else",
        `- Never append it to an actual response (never include "${SILENT_REPLY_TOKEN}" in real replies)`,
        "- Never wrap it in markdown or code blocks",
        "",
        `❌ Wrong: "Here's help... ${SILENT_REPLY_TOKEN}"`,
        `❌ Wrong: "${SILENT_REPLY_TOKEN}"`,
        `✅ Right: ${SILENT_REPLY_TOKEN}`,
        "",
      );
    }

    // 稳定前缀结尾处插入缓存分界标记。
    // SYSTEM_PROMPT_CACHE_BOUNDARY 是一段特殊文字，Pi runtime 及 Provider 层
    // 用它识别 "此行之前为稳定内容，可做 prompt cache 前缀"。
    // 必须是稳定前缀的最后一行，否则缓存锚点偏移。
    lines.push(SYSTEM_PROMPT_CACHE_BOUNDARY);
    return lines.filter(Boolean).join("\n");
  });

  // ─── 阶段 7：构建动态后缀（SYSTEM_PROMPT_CACHE_BOUNDARY 之后） ────────
  // 每次请求都重新生成，不参与稳定缓存键。
  // 放在边界之后是为了让稳定工作区内容作为 byte-identical 前缀跨轮复用。
  // 各段顺序：
  //  1.  动态 Context 文件（如 HEARTBEAT.md —— 每轮内容可能变化）
  //  2.  Webchat Canvas 段（仅 runtimeChannel="webchat"）
  //  3.  Messaging 段（跨会话消息、子 agent 编排指引，仅 full）
  //  4.  Voice/TTS 段（仅 full + 有 ttsHint）
  //  5.  extraSystemPrompt（群聊上下文 / 子 agent 上下文注入）
  //  6.  Reactions 段（Telegram emoji 反馈指引）
  //  7.  Provider dynamicSuffix 插槽
  //  8.  Heartbeat 段（仅 full + 有 heartbeatPrompt）
  //  9.  Runtime 行（agent / host / os / model / channel / capabilities / thinking）
  // 10.  Reasoning 行（/reasoning 开关提示）
  const lines = [stablePrefix];

  lines.push(
    ...buildProjectContextSection({
      files: dynamicContextFiles,
      heading: stableContextFiles.length > 0 ? "# Dynamic Project Context" : "# Project Context",
      dynamic: true,
    }),
  );

  // Channel/session-specific guidance lives below the cache boundary so large
  // stable workspace context can remain a byte-identical prefix across turns.
  lines.push(
    ...buildWebchatCanvasSection({
      isMinimal,
      runtimeChannel,
      canvasRootDir: params.runtimeInfo?.canvasRootDir,
    }),
    ...buildMessagingSection({
      isMinimal,
      availableTools,
      messageChannelOptions,
      inlineButtonsEnabled,
      runtimeChannel,
      messageToolHints: params.messageToolHints,
      sourceReplyDeliveryMode: params.sourceReplyDeliveryMode,
    }),
    ...buildVoiceSection({ isMinimal, ttsHint: params.ttsHint }),
  );

  if (extraSystemPrompt) {
    // extraSystemPrompt 来源于调用方（如群聊成员列表、子 agent fork 上下文等）；
    // minimal 模式（子 agent）使用 "Subagent Context" 标题，
    // full 模式（主 agent）使用 "Group Chat Context" 标题，区分用途。
    const contextHeader =
      promptMode === "minimal" ? "## Subagent Context" : "## Group Chat Context";
    lines.push(contextHeader, extraSystemPrompt, "");
  }
  if (params.reactionGuidance) {
    const { level, channel } = params.reactionGuidance;
    const guidanceText =
      level === "minimal"
        ? [
            `Reactions are enabled for ${channel} in MINIMAL mode.`,
            "React ONLY when truly relevant:",
            "- Acknowledge important user requests or confirmations",
            "- Express genuine sentiment (humor, appreciation) sparingly",
            "- Avoid reacting to routine messages or your own replies",
            "Guideline: at most 1 reaction per 5-10 exchanges.",
          ].join("\n")
        : [
            `Reactions are enabled for ${channel} in EXTENSIVE mode.`,
            "Feel free to react liberally:",
            "- Acknowledge messages with appropriate emojis",
            "- Express sentiment and personality through reactions",
            "- React to interesting content, humor, or notable events",
            "- Use reactions to confirm understanding or agreement",
            "Guideline: react whenever it feels natural.",
          ].join("\n");
    lines.push("## Reactions", guidanceText, "");
  }
  if (providerDynamicSuffix) {
    lines.push(providerDynamicSuffix, "");
  }

  lines.push(...buildHeartbeatSection({ isMinimal, heartbeatPrompt }));

  // Runtime 行与 Reasoning 行：每轮都可能变化（model 切换、channel 变化等），
  // 因此放在动态后缀末尾。
  // · buildRuntimeLine() 序列化 agent/host/os/model/channel/capabilities/thinking 等字段
  // · Reasoning 行告知模型当前的推理可见性设置，便于模型决定是否输出思考过程
  lines.push(
    "## Runtime",
    buildRuntimeLine(runtimeInfo, runtimeChannel, runtimeCapabilities, params.defaultThinkLevel),
    `Reasoning: ${reasoningLevel} (hidden unless on/stream). Toggle /reasoning; /status shows Reasoning when enabled.`,
  );

  return lines.filter(Boolean).join("\n");
}

/**
 * 构建 system prompt 末尾的 Runtime 单行摘要。
 *
 * 格式：`Runtime: agent=main | host=mac-mini | os=Darwin 24.6.0 (arm64) | ...`
 *
 * 该行汇总了本次运行的关键元信息，让模型在每轮都能感知当前的运行环境，
 * 尤其是 channel / capabilities / thinking 等每轮可能变化的字段。
 * · normalizePromptCapabilityIds 对 capabilities 做排序+小写，保证同样能力集的字符串稳定。
 */
export function buildRuntimeLine(
  runtimeInfo?: {
    agentId?: string;
    host?: string;
    os?: string;
    arch?: string;
    node?: string;
    model?: string;
    defaultModel?: string;
    shell?: string;
    repoRoot?: string;
  },
  runtimeChannel?: string,
  runtimeCapabilities: string[] = [],
  defaultThinkLevel?: ThinkLevel,
): string {
  const normalizedRuntimeCapabilities = normalizePromptCapabilityIds(runtimeCapabilities);
  return `Runtime: ${[
    runtimeInfo?.agentId ? `agent=${runtimeInfo.agentId}` : "",
    runtimeInfo?.host ? `host=${runtimeInfo.host}` : "",
    runtimeInfo?.repoRoot ? `repo=${runtimeInfo.repoRoot}` : "",
    runtimeInfo?.os
      ? `os=${runtimeInfo.os}${runtimeInfo?.arch ? ` (${runtimeInfo.arch})` : ""}`
      : runtimeInfo?.arch
        ? `arch=${runtimeInfo.arch}`
        : "",
    runtimeInfo?.node ? `node=${runtimeInfo.node}` : "",
    runtimeInfo?.model ? `model=${runtimeInfo.model}` : "",
    runtimeInfo?.defaultModel ? `default_model=${runtimeInfo.defaultModel}` : "",
    runtimeInfo?.shell ? `shell=${runtimeInfo.shell}` : "",
    runtimeChannel ? `channel=${runtimeChannel}` : "",
    runtimeChannel
      ? `capabilities=${
          normalizedRuntimeCapabilities.length > 0
            ? normalizedRuntimeCapabilities.join(",")
            : "none"
        }`
      : "",
    `thinking=${defaultThinkLevel ?? "off"}`,
  ]
    .filter(Boolean)
    .join(" | ")}`;
}

  // ─── 阶段 7：构建动态后缀（SYSTEM_PROMPT_CACHE_BOUNDARY 之后） ────────
  // 每次请求都重新生成，不参与稳定缓存键。
  // 放在边界之后是为了让稳定工作区内容作为 byte-identical 前缀跨轮复用。
  // 各段顺序：
  //  1.  动态 Context 文件（如 HEARTBEAT.md —— 每轮内容可能变化）
  //  2.  Webchat Canvas 段（仅 runtimeChannel="webchat"）
  //  3.  Messaging 段（跨会话消息、子 agent 编排指引，仅 full）
  //  4.  Voice/TTS 段（仅 full + 有 ttsHint）
  //  5.  extraSystemPrompt（群聊上下文 / 子 agent 上下文注入）
  //  6.  Reactions 段（Telegram emoji 反馈指引）
  //  7.  Provider dynamicSuffix 插槽
  //  8.  Heartbeat 段（仅 full + 有 heartbeatPrompt）
  //  9.  Runtime 行（agent / host / os / model / channel / capabilities / thinking）
  // 10.  Reasoning 行（/reasoning 开关提示）
  const lines = [stablePrefix];

  lines.push(
    ...buildProjectContextSection({
      files: dynamicContextFiles,
      heading: stableContextFiles.length > 0 ? "# Dynamic Project Context" : "# Project Context",
      dynamic: true,
    }),
  );

  // Channel/session-specific guidance lives below the cache boundary so large
  // stable workspace context can remain a byte-identical prefix across turns.
  lines.push(
    ...buildWebchatCanvasSection({
      isMinimal,
      runtimeChannel,
      canvasRootDir: params.runtimeInfo?.canvasRootDir,
    }),
    ...buildMessagingSection({
      isMinimal,
      availableTools,
      messageChannelOptions,
      inlineButtonsEnabled,
      runtimeChannel,
      messageToolHints: params.messageToolHints,
      sourceReplyDeliveryMode: params.sourceReplyDeliveryMode,
    }),
    ...buildVoiceSection({ isMinimal, ttsHint: params.ttsHint }),
  );

  if (extraSystemPrompt) {
    // extraSystemPrompt 来源于调用方（如群聊成员列表、子 agent fork 上下文等）；
    // minimal 模式（子 agent）使用 "Subagent Context" 标题，
    // full 模式（主 agent）使用 "Group Chat Context" 标题，区分用途。
    const contextHeader =
      promptMode === "minimal" ? "## Subagent Context" : "## Group Chat Context";
    lines.push(contextHeader, extraSystemPrompt, "");
  }
  if (params.reactionGuidance) {
    const { level, channel } = params.reactionGuidance;
    const guidanceText =
      level === "minimal"
        ? [
            `Reactions are enabled for ${channel} in MINIMAL mode.`,
            "React ONLY when truly relevant:",
            "- Acknowledge important user requests or confirmations",
            "- Express genuine sentiment (humor, appreciation) sparingly",
            "- Avoid reacting to routine messages or your own replies",
            "Guideline: at most 1 reaction per 5-10 exchanges.",
          ].join("\n")
        : [
            `Reactions are enabled for ${channel} in EXTENSIVE mode.`,
            "Feel free to react liberally:",
            "- Acknowledge messages with appropriate emojis",
            "- Express sentiment and personality through reactions",
            "- React to interesting content, humor, or notable events",
            "- Use reactions to confirm understanding or agreement",
            "Guideline: react whenever it feels natural.",
          ].join("\n");
    lines.push("## Reactions", guidanceText, "");
  }
  if (providerDynamicSuffix) {
    lines.push(providerDynamicSuffix, "");
  }

  lines.push(...buildHeartbeatSection({ isMinimal, heartbeatPrompt }));

  // Runtime 行与 Reasoning 行：每轮都可能变化（model 切换、channel 变化等），
  // 因此放在动态后缀末尾。
  // · buildRuntimeLine() 序列化 agent/host/os/model/channel/capabilities/thinking 等字段
  // · Reasoning 行告知模型当前的推理可见性设置，便于模型决定是否输出思考过程
  lines.push(
    "## Runtime",
    buildRuntimeLine(runtimeInfo, runtimeChannel, runtimeCapabilities, params.defaultThinkLevel),
    `Reasoning: ${reasoningLevel} (hidden unless on/stream). Toggle /reasoning; /status shows Reasoning when enabled.`,
  );

  return lines.filter(Boolean).join("\n");
}

