// ─── 阶段 4：Context 文件分类 ─────────────────────────────────────────
// 将工作区注入文件按 CONTEXT_FILE_ORDER（agents.md→soul.md→identity.md→...）排序后分为两组：
//
// · stableContextFiles（AGENTS.md、SOUL.md、identity.md 等）
//   → 写入稳定前缀 "# Project Context" 段，参与缓存键；
//     内容不变则跨轮次复用同一段 prompt，节省 token 重新编码开销；
//     文件内容变化时 sha256 缓存键自动失效，下轮重新生成。
//
// · dynamicContextFiles（HEARTBEAT.md 等 DYNAMIC_CONTEXT_FILE_BASENAMES 中的文件）
//   → 写入动态后缀 "# Dynamic Project Context" 段，每轮重新生成；
//     不参与缓存键，避免心跳内容频繁变动导致稳定前缀缓存失效。
//
// validContextFiles 过滤掉 path 为空的非法条目，防止生成 "## " 空标题行。
const contextFiles = params.contextFiles ?? [];
const validContextFiles = contextFiles.filter(
  (file) => typeof file.path === "string" && file.path.trim().length > 0,
);
const orderedContextFiles = sortContextFilesForPrompt(validContextFiles);
const stableContextFiles = orderedContextFiles.filter((file) => !isDynamicContextFile(file.path));
const dynamicContextFiles = orderedContextFiles.filter((file) => isDynamicContextFile(file.path));

// bootstrapSystemPromptSections → 拼装 ## Bootstrap Pending 段（bootstrapMode≠none 时非空）：
//   - bootstrapMode="full"  → 生成 "Please read BOOTSTRAP.md..." 完整引导段
//   - bootstrapMode="limited" → 生成 "Bootstrap is still pending but cannot complete here..." 简化提示
//   - includeProjectContext=false：BOOTSTRAP.md 文件内容已在稳定 contextFiles 中注入，此处不重复。
const bootstrapSystemPromptSections = buildAgentBootstrapSystemPromptSections({
  bootstrapMode: params.bootstrapMode,
  bootstrapTruncationNotice: params.bootstrapTruncationNotice,
  contextFiles: orderedContextFiles,
  includeProjectContext: false,
});

