        ]
          .filter(Boolean)
          .join("\n")
      : "",
    params.sandboxInfo?.enabled ? "" : "",

    // ── [14] ## Authorized Senders 段 ────────────────────────────────────
    // 注入 ownerLine 生成的白名单行（仅 full 模式 + ownerLine 非空时非空）。
    // 格式："Authorized senders: <id1>, <id2>. These senders are allowlisted..."
    // isMinimal=true 时 buildUserIdentitySection 返回空数组，该段跳过。
    ...buildUserIdentitySection(ownerLine, isMinimal),

    // ── [15] ## Current Date & Time 段 ───────────────────────────────────
    // 注入 "Time zone: <tz>" 行（仅有 userTimezone 时非空）；
    // 让模型在生成时间相关内容时使用用户本地时区而非 UTC。
    ...buildTimeSection({
      userTimezone,
    }),

    // ── [16] ## Bootstrap Pending 段 ─────────────────────────────────────
    // 注入阶段4预构建的 bootstrapSystemPromptSections（bootstrapMode≠none 时非空）；
    // 告知模型在首轮回复前先执行 BOOTSTRAP.md 工作流（full 模式）或给出受限提示（limited 模式）。
    ...bootstrapSystemPromptSections,

    // ── [17] ## Workspace Files (injected) 标题行 ─────────────────────────
    // 固定的两行说明文字，告知模型下方的 Project Context 内容来自用户可编辑的工作区文件。
    "## Workspace Files (injected)",
    "These user-editable files are loaded by OpenClaw and included below in Project Context.",
    "",

    // ── [18] ## Assistant Output Directives 段 ───────────────────────────
    // 注入 MEDIA:/[[reply_to_*]]/[[audio_as_voice]] 等输出指令规则（仅 full 模式）；
    // 告知模型如何在回复中请求附件投递、引用/回复消息、音频标记等。
    ...buildAssistantOutputDirectivesSection(isMinimal),
  ];

  // ── [19] ## Reasoning Format 段（仅 reasoningTagHint=true 时追加） ───────
  // 强制模型把所有内部推理包裹在 <think>...</think> 标签内，
  // 最终用户可见回复只能出现在 <final>...</final> 中（QwQ 等 Provider 专用格式）。
  if (reasoningHint) {
    lines.push("## Reasoning Format", reasoningHint, "");
  }

  // ── [20] # Project Context 段（稳定 Context 文件） ────────────────────
  // 将阶段4筛出的稳定文件（AGENTS.md、SOUL.md 等）逐个渲染为 "## <path>\n<content>" 块，
  // 汇总在 "# Project Context" 标题下写入稳定前缀。
  // 内容参与缓存键，文件变化时自动失效。
  lines.push(
    ...buildProjectContextSection({
      files: stableContextFiles,
      heading: "# Project Context",
      dynamic: false,
    }),
  );

  // ── [21] ## Silent Replies 段（仅 full 模式 + silentReplyPromptMode≠"none" 时追加） ──
  // 告知模型"无话可说时只回复 SILENT_REPLY_TOKEN，不得附加任何其他内容"；
  // sourceReplyDeliveryMode="message_tool_only" 时禁用该段（回复走 message 工具，不需要 token）。
  if (!isMinimal && silentReplyPromptMode !== "none") {
    lines.push(
      "## Silent Replies",
      `When you have nothing to say, respond with ONLY: ${SILENT_REPLY_TOKEN}`,
      "",
      "⚠️ Rules:",
      "- It must be your ENTIRE message — nothing else",
      `- Never append it to an actual response (never include "${SILENT_REPLY_TOKEN}" in real replies)`,
      "- Never wrap it in markdown or code blocks",
      "",
      `❌ Wrong: "Here's help... ${SILENT_REPLY_TOKEN}"`,
      `❌ Wrong: "${SILENT_REPLY_TOKEN}"`,
      `✅ Right: ${SILENT_REPLY_TOKEN}`,
      "",
    );
  }

  // ── [22] SYSTEM_PROMPT_CACHE_BOUNDARY ─────────────────────────────────
  // 稳定前缀的最后一行；Pi runtime 和 Provider 层用此特殊文字作为 prompt cache 的分割锚点：
  // "此行及之前为稳定内容，可缓存为 byte-identical 前缀；此行之后为动态内容，每轮重新生成"。
  // 必须是 lines 中最后一个非空元素，否则缓存分界点偏移，动态内容会被错误地计入缓存。
  lines.push(SYSTEM_PROMPT_CACHE_BOUNDARY);
  return lines.filter(Boolean).join("\n");
});

