1	import type { StreamFn } from "@mariozechner/pi-agent-core";
2	import type { Api, Model } from "@mariozechner/pi-ai";
3	import type { OpenClawConfig } from "../config/types.openclaw.js";
4	import { resolveProviderStreamFn } from "../plugins/provider-runtime.js";
5	import { createAnthropicMessagesTransportStreamFn } from "./anthropic-transport-stream.js";
6	import {
7	  createAzureOpenAIResponsesTransportStreamFn,
8	  createOpenAICompletionsTransportStreamFn,
9	  createOpenAIResponsesTransportStreamFn,
10	} from "./openai-transport-stream.js";
11	import { getModelProviderRequestTransport } from "./provider-request-config.js";
12	
13	const SUPPORTED_TRANSPORT_APIS = new Set<Api>([
14	  "openai-responses",
15	  "openai-codex-responses",
16	  "openai-completions",
17	  "azure-openai-responses",
18	  "anthropic-messages",
19	  "google-generative-ai",
20	]);
21	
22	const SIMPLE_TRANSPORT_API_ALIAS: Record<string, Api> = {
23	  "openai-responses": "openclaw-openai-responses-transport",
24	  "openai-codex-responses": "openclaw-openai-responses-transport",
25	  "openai-completions": "openclaw-openai-completions-transport",
26	  "azure-openai-responses": "openclaw-azure-openai-responses-transport",
27	  "anthropic-messages": "openclaw-anthropic-messages-transport",
28	  "google-generative-ai": "openclaw-google-generative-ai-transport",
29	};
30	
31	type ProviderTransportStreamContext = {
32	  cfg?: OpenClawConfig;
33	  agentDir?: string;
34	  workspaceDir?: string;
35	  env?: NodeJS.ProcessEnv;
36	};
37	
38	function createProviderOwnedGoogleTransportStreamFn(
39	  model: Model<Api>,
40	  ctx?: ProviderTransportStreamContext,
41	): StreamFn | undefined {
42	  return (
43	    resolveProviderStreamFn({
44	      provider: model.provider,
45	      config: ctx?.cfg,
46	      workspaceDir: ctx?.workspaceDir,
47	      env: ctx?.env,
48	      context: {
49	        config: ctx?.cfg,
50	        agentDir: ctx?.agentDir,
51	        workspaceDir: ctx?.workspaceDir,
52	        provider: model.provider,
53	        modelId: model.id,
54	        model,
55	      },
56	    }) ??
57	    resolveProviderStreamFn({
58	      provider: "google",
59	      config: ctx?.cfg,
60	      workspaceDir: ctx?.workspaceDir,
61	      env: ctx?.env,
62	      context: {
63	        config: ctx?.cfg,
64	        agentDir: ctx?.agentDir,
65	        workspaceDir: ctx?.workspaceDir,
66	        provider: model.provider,
67	        modelId: model.id,
68	        model,
69	      },
70	    }) ??
71	    undefined
72	  );
73	}
74	
75	function createSupportedTransportStreamFn(
76	  model: Model<Api>,
77	  ctx?: ProviderTransportStreamContext,
78	): StreamFn | undefined {
79	  switch (model.api) {
80	    case "openai-responses":
81	    case "openai-codex-responses":
82	      return createOpenAIResponsesTransportStreamFn();
83	    case "openai-completions":
84	      return createOpenAICompletionsTransportStreamFn();
85	    case "azure-openai-responses":
86	      return createAzureOpenAIResponsesTransportStreamFn();
87	    case "anthropic-messages":
88	      return createAnthropicMessagesTransportStreamFn();
89	    case "google-generative-ai":
90	      return createProviderOwnedGoogleTransportStreamFn(model, ctx);
91	    default:
92	      return undefined;
93	  }
94	}
95	
96	function hasTransportOverrides(model: Model<Api>): boolean {
97	  const request = getModelProviderRequestTransport(model);
98	  return Boolean(request?.proxy || request?.tls);
99	}
100	
101	export function isTransportAwareApiSupported(api: Api): boolean {
102	  return SUPPORTED_TRANSPORT_APIS.has(api);
103	}
104	
105	export function resolveTransportAwareSimpleApi(api: Api): Api | undefined {
106	  return SIMPLE_TRANSPORT_API_ALIAS[api];
107	}
108	
109	export function createTransportAwareStreamFnForModel(
110	  model: Model<Api>,
111	  ctx?: ProviderTransportStreamContext,
112	): StreamFn | undefined {
113	  if (!hasTransportOverrides(model)) {
114	    return undefined;
115	  }
116	  if (!isTransportAwareApiSupported(model.api)) {
117	    throw new Error(
118	      `Model-provider request.proxy/request.tls is not yet supported for api "${model.api}"`,
119	    );
120	  }
121	  return createSupportedTransportStreamFn(model, ctx);
122	}
123	
124	export function createOpenClawTransportStreamFnForModel(
125	  model: Model<Api>,
126	  ctx?: ProviderTransportStreamContext,
127	): StreamFn | undefined {
128	  // Explicit fallback callers use this when they need OpenClaw's HTTP
129	  // transport semantics regardless of the default embedded-runner strategy.
130	  // Native OpenAI HTTP still depends on this path for strict tool shaping,
131	  // attribution, cache-boundary stripping, and runtime credential injection.
132	  if (!isTransportAwareApiSupported(model.api)) {
133	    return undefined;
134	  }
135	  return createSupportedTransportStreamFn(model, ctx);
136	}
137	
138	export function createBoundaryAwareStreamFnForModel(
139	  model: Model<Api>,
140	  ctx?: ProviderTransportStreamContext,
141	): StreamFn | undefined {
142	  // Default embedded-runner fallback. Keep OpenAI-family APIs here until PI's
143	  // native HTTP streams preserve the same OpenClaw request contract.
144	  if (!isTransportAwareApiSupported(model.api)) {
145	    return undefined;
146	  }
147	  return createSupportedTransportStreamFn(model, ctx);
148	}
149	
150	export function prepareTransportAwareSimpleModel<TApi extends Api>(
151	  model: Model<TApi>,
152	  ctx?: ProviderTransportStreamContext,
153	): Model<Api> {
154	  const streamFn = createTransportAwareStreamFnForModel(model as Model<Api>, ctx);
155	  const alias = resolveTransportAwareSimpleApi(model.api);
156	  if (!streamFn || !alias) {
157	    return model;
158	  }
159	  return {
160	    ...model,
161	    api: alias,
162	  };
163	}
164	
165	export function buildTransportAwareSimpleStreamFn(
166	  model: Model<Api>,
167	  ctx?: ProviderTransportStreamContext,
168	): StreamFn | undefined {
169	  return createTransportAwareStreamFnForModel(model, ctx);
170	}
